-- YUTOPIA: real TourAPI sample data (no API credentials).

-- Source: https://www.data.go.kr/data/15101578/openapi.do

-- Generated records are identified by provider=TOUR_API and external_id=contentid.

-- Re-running this file updates the same places; it never drops a database.

USE yutopia;

SET NAMES utf8mb4 COLLATE utf8mb4_unicode_ci;

START TRANSACTION;


SET @seed_region_1 = (SELECT MIN(region_id) FROM regions WHERE region_code = CONVERT(X'4c444f4e473a3131' USING utf8mb4) COLLATE utf8mb4_unicode_ci AND parent_id <=> NULL);


SET @seed_region_2 = (SELECT MIN(region_id) FROM regions WHERE region_code = CONVERT(X'4c444f4e473a31313a313130' USING utf8mb4) COLLATE utf8mb4_unicode_ci AND parent_id <=> @seed_region_1);


SET @seed_category_1 = (SELECT MIN(category_id) FROM place_categories WHERE category_name = CONVERT(X'ec97adec82aceab480eab491' USING utf8mb4) COLLATE utf8mb4_unicode_ci AND parent_id <=> NULL);


SET @seed_category_2 = (SELECT MIN(category_id) FROM place_categories WHERE category_name = CONVERT(X'ec97adec82acec9ca0eca081eca780' USING utf8mb4) COLLATE utf8mb4_unicode_ci AND parent_id <=> @seed_category_1);


SET @seed_category_3 = (SELECT MIN(category_id) FROM place_categories WHERE category_name = CONVERT(X'eab3a0eab681' USING utf8mb4) COLLATE utf8mb4_unicode_ci AND parent_id <=> @seed_category_2);

